policy:
policy MakerspaceStockPolicy {
  allow read Materials(material, sheets, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Materials.supplier
  limit order $100 per action
  limit order $200 per day
}

program:
procedure MakerspaceReorder {
  about "Reorder materials below their minimum"
  policy MakerspaceStockPolicy
  sheet Materials "Materials" { material: Text, sheets: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 18:00

  let all = fetch Materials
  let low = filter all where sheets < minimum
  for each i in low up to 2 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $100.00 {
      notify owner "Reorder of {i.material} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.material}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.material}"
  }
}

