procedure BakeryWinBack {
  about "Nudge customers whose pickup date was long ago"
  policy BakeryPolicy
  sheet CakeOrders "CakeOrders" { customer: Text, email: Email, pickup: Date, status: Text, price: Money, address: Text private }
  trigger every day at 08:00

  let all = fetch CakeOrders
  let old = filter all where days_between(pickup, today()) >= 42 and status != "cancelled"
  let oldest = sort old by pickup first 10
  for each r in oldest up to 10 {
    let m = draft email to r.email subject "We miss you": "Hi {r.customer}, it's been a while! We'd love to see you again at the bakery."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

