procedure DentalOutreachCampaign {
  about "On request, contact recent cancelled patients"
  policy DentalPolicy
  sheet Patients "Patients" { name: Text, mobile: Phone, next_visit: DateTime, status: Text, balance: Money, medical_history: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Patients
  let targets = filter all where status == "cancelled" and days_between(next_visit, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.mobile: "Hi {r.name default 'there'}, come back to the office! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

