procedure DentalRefunds {
  about "Handle refund requests within limits"
  policy DentalRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, name: Text, mobile: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 60 {
    notify owner "Refund request {r.request_id} is older than 60 days."
    stop "outside refund window"
  }
  if r.amount > $100.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $100. Please review."
