policy:
policy RetailStockPolicy {
  allow read Stock(product, qty, min_qty, reorder_qty, vendor, cost)
  allow supplier Stock.vendor
  limit order $100 per action
  limit order $200 per day
}

program:
procedure RetailReorder {
  about "Reorder products below their minimum"
  policy RetailStockPolicy
  sheet Stock "Stock" { product: Text, qty: Number, min_qty: Number, reorder_qty: Number, vendor: Text, cost: Money }
  trigger every day at 09:00

  let all = fetch Stock
  let low = filter all where qty < min_qty
  for each i in low up to 2 {
    let cost = i.reorder_qty * i.cost
    if cost > $100.00 {
      notify owner "Reorder of {i.product} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.product}" from i.vendor cost cost, ask owner first timeout 6 hours else skip
    log "ordered {i.product}"
  }
}

procedure GymRefunds {
  about "Handle refund requests within limits"
  policy GymRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, name: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 30 {
    notify owner "Refund request {r.request_id} is older than 30 days."
    stop "outside refund window"
  }
  if r.amount > $50.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $50. Please review."
    stop "over refund limit"
  }
  if r.amount <= $10.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft email to r.email subject "Your refund": "Hi {r.name}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}

