procedure SalonLateBalance {
  about "Remind late clients; escalate very late ones"
  policy SalonPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, status: Text, tab: Money, color_formula: Text private }
  trigger every day at 08:30

  let all = fetch Clients
  let late = filter all where tab > $0.00 and days_between(last_visit, today()) > 7
  for each r in late up to 20 {
    if days_between(r.last_visit, today()) > 21 {
      notify owner "{r.name} is very late ({r.tab}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.name default 'there'}, our records show a tab of {r.tab}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}

