policy WatchesStockPolicy {
  allow read Parts(part, count, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Parts.supplier
  limit order $100 per action
  limit order $400 per day
}

program:
procedure WatchesReorder {
  about "Reorder parts below their minimum"
  policy WatchesStockPolicy
  sheet Parts "Parts" { part: Text, count: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every tuesday at 09:00

  let all = fetch Parts
  let low = filter all where count < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $100.00 {
      notify owner "Reorder of {i.part} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.part}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.part}"
  }
}

