policy:
policy GamestoreStockPolicy {
  allow read Games(title, copies, minimum, reorder_qty, distributor, unit_cost)
  allow supplier Games.distributor
  limit order $200 per action
  limit order $800 per day
}

program:
procedure GamestoreReorder {
  about "Reorder games below their minimum"
  policy GamestoreStockPolicy
  sheet Games "Games" { title: Text, copies: Number, minimum: Number, reorder_qty: Number, distributor: Text, unit_cost: Money }
  trigger every day at 08:00

  let all = fetch Games
  let low = filter all where copies < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.title} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.title}" from i.distributor cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.title}"
  }
}

